#ifndef SCR_TRACK_SAMPLING_H
#define SCR_TRACK_SAMPLING_H

#include "physics/wheel_coordinates.h"
#include <array>
#include <cstdint>
#include <vector>

namespace scr {

// The five per-track arrays are generated by the game. Geometry is the encoded
// database starting at original RAM 0x1ef82, including its two offset tables.
// Retain at most 0x10100 bytes to cover a wrapped 16-bit base plus byte index.
struct TrackGeometryData {
    std::uint8_t segmentCount{};
    std::array<std::uint8_t,100> primaryGeometry{},alternateGeometry{},properties{};
    std::array<std::uint16_t,100> primaryBase{},alternateBase{};
    std::vector<std::uint8_t> geometry;
};
struct TrackSegmentConfiguration {
    std::uint16_t primaryOffset{},alternateOffset{},descriptorOffset{};
    std::uint16_t primaryBase{},alternateBase{};
    std::uint8_t format{},alternateFlag{},slopeFlags{},reverseDirection{},geometryType{};
    std::uint8_t steeringFlags{},limit{},limitDoubled{},maximum{},maximumDoubled{},mode{};
    std::uint8_t directionInversion{},primaryOrientation{},alternateOrientation{},steeringBase{};
};
struct TrackSamplingInputs {
    WheelCoordinates wheels{};
    // Original ADD.W at 0x5c22e reads 0x1bc5e. The modified reference source
    // instead names 0x1bc5c: do not substitute its lateralRoadPosition field.
    std::uint16_t lateralOrigin{},forwardOrigin{};
    std::uint8_t playerSegment{},clampByteAtFF{},speedHighByte{},pitchHighByte{};
};
struct TrackSamplingState {
    TrackSegmentConfiguration segment{};
    std::uint8_t currentSegment{},wheelOffset{},dataIndex{},lateral{},playerLateral{};
    std::uint16_t forwardPosition{},outOfBoundsPosition{};
    std::array<std::uint16_t,4> controls{};
    std::array<std::uint32_t,3> heights{}; // front left, front right, rear center
    std::uint32_t sampledHeight{};
    std::uint8_t outOfBoundsFlag{},renderingOrderMode{},bouncePhase{};
};
struct WheelTrackSample {
    std::uint8_t wheelIndex{},segmentIndex{},lateral{},blend{},reverseDirection{},outOfBoundsFlag{};
    std::uint16_t outOfBoundsPosition{};
    std::array<std::uint16_t,4> controls{};
    std::uint32_t rawHeight{},contactHeight{},sampledHeight{};
};

// Decode the original loadTrackSegmentConfiguration helper for one valid
// segment. Shared by road sampling and steering; does not modify track data.
[[nodiscard]] TrackSegmentConfiguration loadTrackSegmentConfiguration(
    const TrackGeometryData& data,std::uint8_t segmentIndex);

// Original selector [0x5c1d0,0x5c3da), geometry/transition helpers and all three
// interpolation/contact calls. Events are ordered rear, front right, front left.
// Byte/word wrapping, signed comparisons and the absolute RAM[0xff] clamp are
// intentional. Throws for segment counts/indices outside the 100-entry arrays
// or geometry reads outside the supplied database; no emulated CPU state needed.
// Original implementation requires D1/D2 bits 8..15 zero on entry; native typed
// indices express that valid calling convention, not arbitrary register states.
[[nodiscard]] std::array<WheelTrackSample,3> sampleTrackWheelHeights(
    const TrackGeometryData& data,const TrackSamplingInputs& inputs,TrackSamplingState& state);

} // namespace scr
#endif
